			let fragments = [];

			fragments.push({ textKey: intro });
			fragments.push({ textKey: ". " });
			fragments.push({ textKey: "Lost " });
			fragments = fragments.concat(itemsTextVO.textFragments);
			
			return { textFragments: fragments };
