			let isRescueActive = GameGlobals.gameState.getStoryFlag(StoryConstants.flags.RESCUE_EXPLORER_LEFT) && !GameGlobals.gameState.getStoryFlag(StoryConstants.flags.RESCUE_EXPLORER_FOUND);
